"""Prepare paid-work/retained-Alpha tables; no earlier study outcomes are imported."""
from __future__ import annotations

import json
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAPER = ROOT / "paper"
WORKSPACE = ROOT.parents[1]


def columns(*items):
    return [{"key": key, "label": label, **({"kind": kind} if kind else {})} for key, label, kind in items]


def main():
    path = PAPER / "paper_data.json"
    data = json.loads(path.read_text()) if path.exists() else {"status": "working_draft", "version": "working draft; results not bound", "narrative": {}, "tables": {}, "figures": {}}
    config = json.loads(subprocess.check_output(["node", "--input-type=module", "-e", "const c=await import('./model/config.mjs');const w=await import('./model/workflow.mjs');const groups=[['representation'],['certificate'],['representation','certificate'],['experiment']];const construction=['B retention','C optional research'].flatMap(lane=>groups.map(keys=>{const retention=lane.startsWith('B');const workUnits=keys.reduce((n,k)=>n+c.ASSETS[k][retention?'retentionWorkUnits':'researchWorkUnits'],0);const cfg=retention?{...c.BASE,assetConstructionMultiplier:c.BASE.retentionCostMultiplier}:c.BASE;return{id:keys.join(' + '),lane,workUnits,plan:w.planConstruction(cfg,{workUnits,keys})}}));console.log(JSON.stringify({...c,DEFAULT_WORKFLOW_CONFIG:w.DEFAULT_WORKFLOW_CONFIG,ROLE_BUDGETS:w.ROLE_BUDGETS,construction}));"], cwd=ROOT, text=True))
    models = json.loads((ROOT / "evidence" / "frontier_model_recheck.json").read_text())
    tables = data["tables"]
    tables["job_class"] = {"caption": "Supported module classes in the supplied venture catalogue. Complexity, arrival mix and price/value factors are assumptions; larger scope is not priced as the base module.", "columns": columns(("name", "Module family", None), ("share", "Mix", "percent"), ("complexity", "Resource factor", "number"), ("humanFactor", "Human factor", "number"), ("valueFactor", "Value factor", "number"), ("deadline", "AI weeks", "number")), "rows": config["JOB_CLASSES"], "note": "Factors are relative to the base matched module. Buyer value is varied independently from the human reference. AI weeks is the provider’s offered turnaround/resource window, not a universal buyer deadline; the human alternative has its own assumed lead time and delay utility. Aggregate delivery comparisons must use the same task mix for the matched human price, offered price and complete cost."}
    tables["transformation"] = {
        "caption": "Supplied candidate mechanisms. Paid-work learning, incremental retention and admission are simulated; none is an observed autonomous invention.",
        "columns": columns(("asset", "Candidate", None), ("change", "Restriction and mechanism", None), ("falsifier", "Purpose bridge and decisive failure", None)),
        "widths": [.19, .35, .38],
        "rows": [
            {"asset": "Representation + certificate bundle", "change": "Repeated formulation and reconstruction burden. A traceable constraint representation and compatible search/checking adapter are jointly retained; isolated components may add overhead.", "falsifier": "Recompute original constraints and objective; compare neither, each component and the bundle. Reject if the gain vanishes at full cost or a changed encoding omits a hard constraint."},
            {"asset": "Counterexample experiment protocol", "change": "Expensive evaluation of weak candidates. A family-specific informative screen rejects some mechanical failures before full evaluation; competent Beta already has a substantial screen. False rejections remain possible.", "falsifier": "Fresh independent campaigns, full evaluation after screening, zero-increment control and full amortization. Charge missed useful candidates, screening and shared semantic blindness."},
            {"asset": "Network discovery and optional adoption", "change": "After shareable admission all eligible members can discover the asset. Heterogeneous recipients may adopt, reconstruct or decline after scope and cost checks.", "falsifier": "Fresh disjoint recipient work against competent available Beta; equal agents/compute. Reject apparent gains from overlap, additional resources, failed adaptation or uncharged distribution."},
            {"asset": "Versioned revalidation as Beta moves", "change": "An assumed future frontier/solver improvement can absorb previously additional advantage. Admission evidence expires and is reassessed against the new baseline.", "falsifier": "Retire or supersede net-zero assets; stale historical evidence cannot restore influence. Report new Alpha and erosion after revalidation cost."},
        ],
        "note": "The finite catalogue and effect assumptions are supplied. A paid job may leave a candidate, not guaranteed Alpha. B charges only additional retention work; optional C is a separate path. Commercial Beta profit, net Alpha, recipient benefit and improved invention efficacy are separate results.",
    }
    tables["contrast"] = {
        "caption": "Contrasting venture scopes. These are bounded market/scope comparisons, not independent claims of realized autonomous delivery.",
        "columns": columns(("venture", "Offering", None), ("asset", "Complete asset", None), ("boundary", "Commercial and validation boundary", None)),
        "widths": [.21, .29, .42],
        "rows": [
            {"venture": "Simulation-native engineering", "asset": "Candidate parameterization, simulator and uncertainty report.", "boundary": "Assumed 120–360 person-hours and broad $14,760–$84,600 labor envelope for a computational concept. Physical validation and certified design are outside this fee/scope."},
            {"venture": "Verified bespoke software", "asset": "Narrow module, explicit contracts, proof or independent oracle, regression and adapter.", "boundary": "Assumed 104/176/312 human hours at reported architecture/programming/QA/coordination rates. Verification is relative to a specification, not unstated intent."},
            {"venture": "Coordination-mechanism lab", "asset": "Executable allocation/incentive protocol with adversarial simulations.", "boundary": "Deferred: real preference and strategic-behavior data dominate external validity; no measured demand or comparable complete project fee obtained."},
        ],
    }
    model_rows = []
    for model in models["models"]:
        r = model["standard_usd_per_million"]
        model_rows.append({"model": model["id"], "mode": model["selected_mode"] + "/" + model["selected_effort"], "input": r["ordinary_input"], "read": r["cache_read"], "write": r["cache_write_30m"], "output": r["output_including_reasoning"]})
    tables["model"] = {"caption": "Official API token rates used in the model, USD per million tokens, checked 26 October 2026. Alias versions are recorded; no immutable date snapshot was available in the inspected record.", "columns": columns(("model", "Model", None), ("mode", "Mode/effort", None), ("input", "Input", "money"), ("read", "Cache read", "money"), ("write", "30m write", "money"), ("output", "Output", "money")), "rows": model_rows, "note": "Output includes reasoning and billed internal Pro work. Requests are assumed split at no more than 200k input and 128k output tokens; long-context premiums therefore do not apply to these modeled short requests. The 12-hour cache-write alternatives are documented but not used. API charges are separate from subscriptions."}
    params = [
        ("weeks", "Service weeks"), ("runoffWeeks", "Runoff weeks"), ("seedCapital", "Seed capital, USD"), ("historicalResearchAllowance", "Historical development allowance, USD"), ("setupCost", "Setup expense, USD"), ("overheadMonthly", "Monthly overhead incl. subscription, USD"), ("operatorSubscriptionMonthly", "Of which subscription allocation, USD"), ("runoffOverheadMonthly", "Monthly runoff overhead, USD"), ("humanReference", "Base human-team reference, USD"), ("prospectsMonthly", "Prospects/month before shocks"), ("buyerValueMedian", "Assumed median buyer value, USD"), ("buyerValueSpread", "Buyer value spread"), ("trustMax", "Maximum trust burden, USD"), ("switchingCost", "Initial switching burden, USD"), ("buyerDelayCostWeekly", "Buyer delay burden/week, USD"), ("initialPerceivedQuality", "AI conditional correctness belief"), ("humanQuality", "Human conditional correctness belief"), ("humanDeliveryWeeks", "Human quoted lead time, weeks"), ("initialCompletionBelief", "AI accepted-improvement belief"), ("humanCompletionBelief", "Human accepted-improvement belief"), ("repeatProbability", "Repeat probability"), ("commodityShare", "No-bespoke-value share"), ("scopeSupport", "Supported input share"), ("acquisitionCostPerProspect", "Acquisition expense/prospect, USD"), ("collectionDelayWeeks", "Base collection delay, weeks"), ("badDebt", "Bad debt probability"), ("paymentFee", "Payment fee fraction"), ("taxReserve", "Tax/liquidity reserve fraction"), ("refundReserve", "Refund reserve fraction"), ("minimumCashReserve", "Minimum cash reserve, USD"), ("concurrency", "Concurrent workflow slots"), ("inputQuotaWeekly", "Input tokens/week"), ("outputQuotaWeekly", "Output tokens/week"), ("cpuHoursWeekly", "Solver CPU-hours/week"), ("validatorHoursWeekly", "Validator CPU-hours/week"), ("queueLimit", "Queued-work limit"), ("queueWaitLimit", "Queue deadline, weeks"), ("commonError", "Shared interpretation error probability"), ("initialError", "Ordinary initial-error parameter"), ("improvementProbability", "Candidate-improvement probability"), ("semanticDetection", "Semantic error detection"), ("mechanicalDetection", "Mechanical error detection"), ("correctionSuccess", "Correction success"), ("maxRetries", "Maximum corrections"), ("assetProductiveProbability", "Productive construction probability"), ("assetFalseAdmission", "False admission probability"), ("assetFalseRejection", "False rejection probability"), ("assetLifetimeWeeks", "Asset useful life, weeks"), ("assetTransferSuccess", "Transfer success probability"), ("assetMaintenanceWeekly", "Asset maintenance/week, USD"), ("copyHazardWeekly", "Weekly copying/overlap hazard"), ("forecastHaircut", "Forecast workload haircut"), ("betaUpgradeWeek", "Hypothetical Beta upgrade week"), ("betaUpgradeResourceFactor", "Future Beta resource factor"), ("betaBundleAbsorption", "Bundle advantage absorbed by Beta"), ("betaExperimentAbsorption", "Experiment advantage absorbed by Beta"), ("alphaProbeCount", "Fresh initial Alpha probes"), ("alphaRevalidationProbeCount", "Fresh revalidation probes"), ("alphaEvidenceWeeks", "Alpha evidence freshness, weeks"), ("alphaPublicationCost", "Root/publication cost, USD"), ("alphaAccessCostPerUse", "Capability access/use cost, USD"), ("alphaDistributionCostPerMember", "Distribution/member cost, USD"),
    ]
    params += [("paidLearningProbability", "Candidate emergence / accepted job"), ("rightsClearedProbability", "Reusable rights clearance probability"), ("retentionCostMultiplier", "Incremental B resource multiplier"), ("assetConstructionMultiplier", "Optional C research multiplier")]
    scenarios = {s["id"]: s for s in config["SCENARIOS"]}
    tables["parameter"] = {"caption": "Frozen primary parameters (source file is authoritative). Quality, behavior, effort, demand, capacity and construction effects are assumptions; reported prices are separately identified. Final binding refreshes this table from the frozen configuration.", "columns": columns(("parameter", "Parameter", None), ("conservative", "Conservative", "number"), ("central", "Central", "number"), ("favorable", "Favorable", "number")), "rows": [{"parameter": label, **{s: scenarios[s].get(k) for s in scenarios}} for k, label in params], "long": True, "note": "The independent register retains all parameters, declared price and policy grids, and source identities. Human price and buyer value vary separately."}
    tables["workflow"] = {"caption": "Per-unit role usage assumptions. Input/output are thousands of tokens; output includes reasoning. Repetition, complexity, correction and assets change units. These are not measured production traces.", "columns": columns(("role", "Automated role", None), ("model", "Model", None), ("input", "Input k", "number"), ("output", "Output k", "number")), "rows": [{"role": name, "model": role["model"].replace("gpt-", ""), "input": role["input"] / 1000, "output": role["output"] / 1000} for name, role in config["ROLE_BUDGETS"].items()], "note": "All producer, validator, correction, capability evaluator and packaging roles are automated. Shared semantic errors can survive retries. Capacity booking uses blind maximum reservations; modeled completion latency is not a measured API SLA."}
    tables["construction"] = {"caption": "Central incremental B retention and optional C research resource assumptions, before separate held-out admission. Work units are resource counts, not dollar budgets. Neither path recharges A paid-job development.", "columns": columns(("asset", "Ledger / candidate", None), ("units", "Work units", "number"), ("input", "Input M", "number"), ("output", "Output M", "number"), ("cpu", "CPU h", "number"), ("cost", "Cost USD", "money")), "rows": [{"asset": row["lane"] + ': ' + row["id"].replace("_", " "), "units": row["workUnits"], "input": row["plan"]["tokens"]["input"] / 1e6, "output": row["plan"]["tokens"]["output"] / 1e6, "cpu": row["plan"]["resources"]["cpuHours"] / 1, "cost": row["plan"]["costCents"] / 100} for row in config["construction"]], "note": "All resource quantities and the small retention workload are assumptions. B covers only remaining extraction/generalization/packaging/integration work; C is a separately optional search beyond paid scope. Fresh Alpha probes, independent admission, distribution, transfer, upkeep, later revalidation and displaced delivery add to these amounts. Rejections and failures remain charged. The complete ledger is authoritative."}
    data["source_binding"] = {"market": "evidence/market_calibration.json", "model": "evidence/frontier_model_recheck.json", "gym": "evidence/gym_specialist_successor_source.json", "configuration": "model/config.mjs", "workflow": "model/workflow.mjs", "note": "Static table refresh only. Final result values require separate explicit binding after protocol freeze."}
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n")
    print(path)


if __name__ == "__main__":
    main()
